// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(uint8 callCount) public {
        uint8 plays = uint8(bound(callCount, 0, 50));

        address player = makeAddr("player");
        vm.deal(player, type(uint256).max);
        vm.startPrank(player);

        for (uint8 i = 0; i < plays; i++) {
            c.play{value: 10}();
        }
        vm.stopPrank();

        assertTrue(c.pot() % 10 == 0, "pot should be multiple of TICKET_AMOUNT (10)");
    }
}
